    Payment = apps.get_model("rms", "Payment")
    PurchaseLine = apps.get_model("rms", "PurchaseLine")
    OrderItem.objects.filter(order__stock_deducted=True).update(deducted=True)
    rows = []
    for o in Order.objects.filter(is_paid=True).only("id", "total", "payment_method", "paid_at", "created_at"):
        rows.append(Payment(order_id=o.id, method=o.payment_method or "cash", amount=o.total,
                            tendered=o.total, created_at=o.paid_at or o.created_at))
        if len(rows) >= 500:
            Payment.objects.bulk_create(rows)
            rows = []
    if rows:
        Payment.objects.bulk_create(rows)
    for l in PurchaseLine.objects.filter(po__status="received"):
        l.received_qty = l.qty
        l.save(update_fields=["received_qty"])


